L296: /* Check whether a file maybe a pyc file: Look at the extension,
L297:    the file type, and, if we may close it, at the first few bytes. */
L298: static int
L299: maybe_pyc_file(FILE *fp, PyObject *filename, int closeit)
L300: {
L301:     PyObject *ext = PyUnicode_FromString(".pyc");
L302:     if (ext == NULL) {
L303:         return -1;
L304:     }
L305:     Py_ssize_t endswith = PyUnicode_Tailmatch(filename, ext, 0, PY_SSIZE_T_MAX, +1);
L306:     Py_DECREF(ext);
L307:     if (endswith) {
L308:         return 1;
L309:     }
L310: 
L311:     /* Only look into the file if we are allowed to close it, since
L312:        it then should also be seekable. */
L313:     if (!closeit) {
L314:         return 0;
L315:     }
L316:     /* Read only two bytes of the magic. If the file was opened in
L317:        text mode, the bytes 3 and 4 of the magic (\r\n) might not
L318:        be read as they are on disk. */
L319:     unsigned int halfmagic = PyImport_GetMagicNumber() & 0xFFFF;
L320:     unsigned char buf[2];
L321:     /* Mess:  In case of -x, the stream is NOT at its start now,
L322:        and ungetc() was used to push back the first newline,
L323:        which makes the current stream position formally undefined,
L324:        and a x-platform nightmare.
L325:        Unfortunately, we have no direct way to know whether -x
L326:        was specified.  So we use a terrible hack:  if the current
L327:        stream position is not 0, we assume -x was specified, and
L328:        give up.  Bug 132850 on SourceForge spells out the
L329:        hopelessness of trying anything else (fseek and ftell
L330:        don't work predictably x-platform for text-mode files).
L331:     */
L332:     int ispyc = 0;
L333:     if (ftell(fp) == 0) {
L334:         if (fread(buf, 1, 2, fp) == 2 &&
L335:             ((unsigned int)buf[1]<<8 | buf[0]) == halfmagic)
L336:             ispyc = 1;
L337:         rewind(fp);
L338:     }
L339:     return ispyc;
L340: }
